"""Runtime support for vecDSL programs generated for Milvus with pymilvus. Generated by vecDSL 7. Do not edit."""

from __future__ import annotations

import csv
import json
import math
import os
import random
import re
import time
import urllib.request
import warnings
from datetime import datetime, timezone
from importlib.metadata import PackageNotFoundError, version
from typing import Any, Callable, Iterable, Iterator, Sequence

SDK_PACKAGE = "{{sdk.python.package}}"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"
SERVER_SERIES = "{{server.series}}"
LITE_PACKAGE = "{{lite.package}}"

_PLACEHOLDER = re.compile(r"\{([A-Za-z_][A-Za-z0-9_]*)\}")
_DURATION = re.compile(r"^\s*(\d+(?:\.\d+)?)\s*(ms|s|m|h|d|w)\s*$")
_DURATION_SECONDS = {"ms": 0.001, "s": 1, "m": 60, "h": 3600, "d": 86400, "w": 604800}
_PAGE = 1000


class UnsupportedFeature(NotImplementedError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()


def unsupported(vendor: str, feature: str) -> None:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


_endpoints: dict[int, dict[str, Any]] = {}


def connect(factory: Callable[..., Any], timeout: float | None = None, **options: Any) -> Any:
    """Opens a client, waiting for a server that is still starting (for example a fresh docker compose up)."""
    limit = float(os.environ.get("VECDSL_CONNECT_TIMEOUT", "120")) if timeout is None else timeout
    deadline = time.monotonic() + limit
    while True:
        try:
            client = factory(**options)
            _endpoints[id(client)] = options
            return client
        except Exception:
            if time.monotonic() >= deadline:
                raise
            time.sleep(2)


_server_versions: dict[int, str] = {}


def server_version(client: Any) -> str:
    key = id(client)
    if key not in _server_versions:
        _server_versions[key] = str(client.get_server_version())
    return _server_versions[key]


def is_lite(client: Any) -> bool:
    return server_version(client).startswith("milvus_lite")


def check_server(client: Any) -> str:
    found = server_version(client)
    if not is_lite(client) and _version_tuple(found)[:2] != _version_tuple(SERVER_SERIES):
        warnings.warn(f"program generated for Milvus {SERVER_SERIES}.x is connected to Milvus {found}", RuntimeWarning,
                      stacklevel=2)
    return found


def require_server(client: Any, feature: str) -> None:
    if is_lite(client):
        unsupported(LITE_PACKAGE, feature)


def lit(value: Any) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, (list, tuple, set)):
        return "[" + ", ".join(lit(item) for item in value) + "]"
    raise TypeError(f"cannot use {type(value).__name__} in a Milvus filter expression")


def expr(template: str, **values: Any) -> str:
    return _PLACEHOLDER.sub(lambda match: lit(values[match.group(1)]) if match.group(1) in values else match.group(0),
                            template)


def time_value(value: Any) -> float:
    if isinstance(value, (int, float)):
        return value
    text = str(value).strip()
    if text == "now":
        return time.time()
    match = _DURATION.match(text)
    if match:
        return float(match.group(1)) * _DURATION_SECONDS[match.group(2)]
    moment = datetime.fromisoformat(text.replace("Z", "+00:00"))
    if moment.tzinfo is None:
        moment = moment.replace(tzinfo=timezone.utc)
    return moment.timestamp()


def similarity(metric: str, distance: float) -> float:
    if metric == "L2":
        return -math.sqrt(max(distance, 0.0))
    if metric == "HAMMING":
        return -distance
    if metric == "JACCARD":
        return 1.0 - distance
    return distance


def hits(results: Sequence[Sequence[Any]], metric: str, native: bool = False, max_score: float | None = None,
         primary_key: str | None = None) -> list[dict[str, Any]]:
    rows = []
    for hit in results[0] if results else []:
        score = hit["distance"] if native else similarity(metric, hit["distance"])
        if max_score is not None and score > max_score:
            continue
        entity = dict(hit.get("entity") or {})
        key = hit.get("id", entity.get(primary_key) if primary_key else None)
        rows.append({"id": key, "score": score, **{k: v for k, v in entity.items() if k != primary_key}})
    return rows


def has_collection(client: Any, collection_name: str) -> bool:
    return client.has_collection(collection_name)


def has_database(client: Any, db_name: str) -> bool:
    return db_name in client.list_databases()


def _batches(rows: Sequence[dict[str, Any]], size: int) -> Iterator[list[dict[str, Any]]]:
    for start in range(0, len(rows), size):
        yield list(rows[start:start + size])


def read_records(location: str, format: str | None = None) -> list[dict[str, Any]]:
    path = location[len("file://"):] if location.startswith("file://") else location
    if "://" in path:
        raise UnsupportedFeature(f"reading records from {location} requires server-side bulk import")
    kind = (format or os.path.splitext(path)[1].lstrip(".")).lower()
    if kind in ("json", "jsonl", "ndjson"):
        with open(path, encoding="utf-8") as handle:
            text = handle.read().strip()
        if text.startswith("["):
            return json.loads(text)
        return [json.loads(line) for line in text.splitlines() if line.strip()]
    if kind == "csv":
        with open(path, encoding="utf-8", newline="") as handle:
            return list(csv.DictReader(handle))
    if kind == "parquet":
        import pyarrow.parquet as parquet
        return parquet.read_table(path).to_pylist()
    raise UnsupportedFeature(f"record format {kind}")


def _partition(partition_name: str | None) -> dict[str, Any]:
    return {"partition_name": partition_name} if partition_name else {}


def _with_defaults(rows: Iterable[dict[str, Any]], defaults: dict[str, Any] | None) -> list[dict[str, Any]]:
    return [{**(defaults or {}), **row} for row in rows]


def _existing_ids(client: Any, collection_name: str, primary_key: str, ids: Sequence[Any]) -> set[Any]:
    found: set[Any] = set()
    for start in range(0, len(ids), _PAGE):
        chunk = list(ids[start:start + _PAGE])
        found.update(row[primary_key] for row in client.get(collection_name, ids=chunk, output_fields=[primary_key]))
    return found


def insert_rows(client: Any, collection_name: str, rows: Iterable[dict[str, Any]], primary_key: str,
                on_conflict: str = "error", partition_name: str | None = None,
                defaults: dict[str, Any] | None = None, batch_size: int = _PAGE) -> dict[str, int]:
    records = _with_defaults(rows, defaults)
    if on_conflict in ("update", "replace"):
        return upsert_rows(client, collection_name, records, partition_name=partition_name, batch_size=batch_size)
    ids = [row[primary_key] for row in records if primary_key in row]
    duplicates = _existing_ids(client, collection_name, primary_key, ids) if ids else set()
    if duplicates and on_conflict == "error":
        raise ValueError(f"{len(duplicates)} records already exist in {collection_name}: {sorted(map(str, duplicates))[:10]}")
    records = [row for row in records if row.get(primary_key) not in duplicates]
    inserted = 0
    for chunk in _batches(records, batch_size):
        inserted += client.insert(collection_name, chunk, **_partition(partition_name))["insert_count"]
    return {"insert_count": inserted, "skipped": len(duplicates)}


def upsert_rows(client: Any, collection_name: str, rows: Iterable[dict[str, Any]], partition_name: str | None = None,
                defaults: dict[str, Any] | None = None, batch_size: int = _PAGE) -> dict[str, int]:
    upserted = 0
    for chunk in _batches(_with_defaults(rows, defaults), batch_size):
        upserted += client.upsert(collection_name, chunk, **_partition(partition_name))["upsert_count"]
    return {"upsert_count": upserted}


def _function_outputs(client: Any, collection_name: str) -> set[str]:
    functions = client.describe_collection(collection_name).get("functions") or []
    return {name for function in functions for name in function.get("output_field_names", [])}


def update_rows(client: Any, collection_name: str, primary_key: str, ids: Sequence[Any] | None = None,
                filter: str | None = None, values: dict[str, Any] | None = None,
                rows: Iterable[dict[str, Any]] | None = None, mode: str = "merge",
                remove: Sequence[str] | None = None, partition_name: str | None = None) -> dict[str, int]:
    replacements = {row[primary_key]: row for row in rows or []}
    if not ids and filter is None:
        if not replacements:
            raise ValueError("update requires ids, a filter or records")
        ids = list(replacements)
    scope = [partition_name] if partition_name else None
    if ids:
        current_rows = get_rows(client, collection_name, ids, ["*"], partition_names=scope)
    else:
        current_rows = scroll(client, collection_name, filter=filter, output_fields=["*"], partition_names=scope)
    derived = _function_outputs(client, collection_name)
    updated = []
    for current in current_rows:
        key = current[primary_key]
        merged = {k: v for k, v in current.items() if k not in derived} if mode == "merge" else {primary_key: key}
        merged.update(replacements.get(key, {}))
        merged.update(values or {})
        for name in remove or ():
            merged[name] = None
        updated.append(merged)
    return upsert_rows(client, collection_name, updated, partition_name=partition_name)


def delete_rows(client: Any, collection_name: str, ids: Sequence[Any] | None = None, filter: str | None = None,
                partition_name: str | None = None) -> dict[str, int]:
    if ids:
        result = client.delete(collection_name, ids=list(ids), **_partition(partition_name))
    else:
        result = client.delete(collection_name, filter=filter or "", **_partition(partition_name))
    return {"delete_count": int(result.get("delete_count", 0)) if isinstance(result, dict) else len(result)}


def get_rows(client: Any, collection_name: str, ids: Sequence[Any], output_fields: Sequence[str],
             partition_names: Sequence[str] | None = None, consistency_level: str | None = None) -> list[dict[str, Any]]:
    options: dict[str, Any] = {"partition_names": list(partition_names)} if partition_names else {}
    if consistency_level:
        options["consistency_level"] = consistency_level
    return [dict(row) for row in client.get(collection_name, ids=list(ids), output_fields=list(output_fields), **options)]


def count(client: Any, collection_name: str, filter: str = "", partition_names: Sequence[str] | None = None,
          consistency_level: str | None = None) -> int:
    options: dict[str, Any] = {"partition_names": list(partition_names)} if partition_names else {}
    if consistency_level:
        options["consistency_level"] = consistency_level
    result = client.query(collection_name, filter=filter, output_fields=["count(*)"], **options)
    return int(result[0]["count(*)"])


def scroll(client: Any, collection_name: str, filter: str = "", output_fields: Sequence[str] | None = None,
           limit: int | None = None, offset: int | None = None, partition_names: Sequence[str] | None = None,
           consistency_level: str | None = None) -> list[dict[str, Any]]:
    options: dict[str, Any] = {"partition_names": list(partition_names)} if partition_names else {}
    if limit is not None:
        options["limit"] = limit
    if offset:
        options["offset"] = offset
    if consistency_level:
        options["consistency_level"] = consistency_level
    iterator = client.query_iterator(collection_name, batch_size=_PAGE, filter=filter,
                                     output_fields=list(output_fields or []), **options)
    rows: list[dict[str, Any]] = []
    try:
        while True:
            batch = iterator.next()
            if not batch:
                return rows
            rows.extend(dict(row) for row in batch)
    finally:
        iterator.close()


def lookup_vector(client: Any, collection_name: str, field: str, id: Any) -> list[float]:
    rows = client.get(collection_name, ids=[id], output_fields=[field])
    if not rows:
        raise KeyError(f"record {id!r} not found in {collection_name}")
    return rows[0][field]


def _is_vector(item: Any) -> bool:
    return isinstance(item, (list, tuple))


def example_ids(positives: Sequence[Any], negatives: Sequence[Any] = ()) -> list[Any]:
    return [item for item in [*positives, *negatives] if not _is_vector(item)]


def recommend_vector(client: Any, collection_name: str, field: str, positives: Sequence[Any],
                     negatives: Sequence[Any] = ()) -> list[float]:
    def resolve(items: Sequence[Any]) -> list[list[float]]:
        vectors = [list(item) for item in items if _is_vector(item)]
        keys = [item for item in items if not _is_vector(item)]
        if keys:
            vectors.extend(row[field] for row in client.get(collection_name, ids=keys, output_fields=[field]))
        return vectors

    positive = resolve(positives)
    negative = resolve(negatives)
    if not positive:
        raise ValueError("recommend requires at least one positive example")
    centroid = [sum(values) / len(positive) for values in zip(*positive)]
    if negative:
        anti = [sum(values) / len(negative) for values in zip(*negative)]
        centroid = [2 * c - a for c, a in zip(centroid, anti)]
    return centroid


def _pairwise(metric: str, left: Sequence[float], right: Sequence[float]) -> float:
    if metric == "L2":
        return -math.sqrt(sum((a - b) ** 2 for a, b in zip(left, right)))
    dot = sum(a * b for a, b in zip(left, right))
    if metric == "COSINE":
        norm = math.sqrt(sum(a * a for a in left)) * math.sqrt(sum(b * b for b in right))
        return dot / norm if norm else 0.0
    if metric == "IP":
        return dot
    raise UnsupportedFeature(f"distance matrix for metric {metric}")


def distance_matrix(client: Any, collection_name: str, field: str, metric: str, primary_key: str,
                    sample: int = 100, limit: int = 10, filter: str = "",
                    consistency_level: str | None = None) -> list[dict[str, Any]]:
    options: dict[str, Any] = {"consistency_level": consistency_level} if consistency_level else {}
    rows = client.query(collection_name, filter=filter, output_fields=[primary_key, field], limit=sample, **options)
    result = []
    for row in rows:
        scored = sorted(
            ({"id": other[primary_key], "score": _pairwise(metric, row[field], other[field])}
             for other in rows if other[primary_key] != row[primary_key]),
            key=lambda entry: entry["score"], reverse=True)
        result.append({"id": row[primary_key], "neighbours": scored[:limit]})
    return result


def compact(client: Any, collection_name: str, wait: bool = True, timeout: float | None = None) -> dict[str, Any]:
    job_id = client.compact(collection_name)
    if not wait:
        return {"compaction_id": job_id}
    deadline = None if timeout is None else time.monotonic() + timeout
    while True:
        state = str(client.get_compaction_state(job_id))
        if state.lower() in ("completed", "compactionstatecompleted"):
            return {"compaction_id": job_id, "state": state}
        if deadline is not None and time.monotonic() > deadline:
            raise TimeoutError(f"compaction {job_id} did not finish within {timeout} s")
        time.sleep(1)


def _describe_index(client: Any, collection_name: str, index_name: str, field_name: str) -> dict[str, Any]:
    try:
        return dict(client.describe_index(collection_name, index_name))
    except Exception:
        return dict(client.describe_index(collection_name, field_name))


def await_index(client: Any, collection_name: str, index_name: str, field_name: str, until: str = "ready",
                timeout: float | None = None) -> dict[str, Any]:
    deadline = None if timeout is None else time.monotonic() + timeout
    while True:
        info = _describe_index(client, collection_name, index_name, field_name)
        state = str(info.get("state", "Finished")).lower()
        if "fail" in state:
            if until == "failed":
                return info
            raise RuntimeError(f"index {index_name} on {collection_name} failed: {info.get('index_state_fail_reason', '')}")
        if until in ("pending", "building") or (state == "finished" and not info.get("pending_index_rows")):
            return info
        if deadline is not None and time.monotonic() > deadline:
            raise TimeoutError(f"index {index_name} on {collection_name} not ready within {timeout} s")
        time.sleep(1)


def describe(client: Any, collection_name: str, stats: bool = False, index_progress: bool = False) -> dict[str, Any]:
    result: dict[str, Any] = {"collection": client.describe_collection(collection_name)}
    if stats:
        result["stats"] = client.get_collection_stats(collection_name)
    if index_progress:
        result["indexes"] = {name: dict(client.describe_index(collection_name, name))
                             for name in client.list_indexes(collection_name)}
    return result


def list_objects(client: Any, kind: str, scope: str | None = None, prefix: str | None = None,
                 limit: int | None = None, only: Sequence[str] | None = None) -> list[str]:
    if kind == "collections":
        names = client.list_collections()
    elif kind == "databases":
        names = client.list_databases()
    elif kind == "indexes":
        names = client.list_indexes(scope)
    elif kind == "partitions":
        names = client.list_partitions(scope)
    elif kind == "aliases":
        names = client.list_aliases(scope or "")["aliases"]
    elif kind in ("tenants", "namespaces"):
        names = [name for name in client.list_partitions(scope) if name in (only or ())]
    elif kind == "snapshots":
        names = sorted(name for collection in ([scope] if scope else client.list_collections())
                       for name in client.list_snapshots(collection_name=collection))
    else:
        raise UnsupportedFeature(f"listing {kind}")
    names = sorted(name for name in names if not prefix or name.startswith(prefix))
    return names[:limit] if limit else names


def has_partition(client: Any, collection_name: str, partition_name: str) -> bool:
    return client.has_partition(collection_name, partition_name)


def drop_field(client: Any, collection_name: str, field_name: str) -> None:
    client.drop_collection_field(collection_name, field_name=field_name)


def alter_field(client: Any, collection_name: str, field_name: str, field_params: dict[str, Any]) -> None:
    client.alter_collection_field(collection_name, field_name=field_name, field_params=field_params)


def add_file_resource(client: Any, name: str, path: str) -> None:
    client.add_file_resource(name=name, path=path)


def remove_file_resource(client: Any, name: str) -> None:
    client.remove_file_resource(name=name)


ANALYZER_PROBE = "vecDSL Analyzer CHECK"


def check_analyzer(client: Any, analyzer_params: dict[str, Any]) -> list[str]:
    """Runs the analyzer on the server over a fixed text; the server rejects analyzer settings it cannot build."""
    return list(client.run_analyzer(ANALYZER_PROBE, analyzer_params=analyzer_params).tokens)


def _keys(client: Any, collection_name: str, primary_key: str, filter: str = "",
          partition_names: Sequence[str] | None = None) -> list[Any]:
    return sorted(row[primary_key] for row in scroll(client, collection_name, filter=filter, output_fields=[primary_key],
                                                     partition_names=partition_names))


def delete_matching(client: Any, collection_name: str, primary_key: str, filter: str = "",
                    partition_name: str | None = None, limit: int | None = None) -> dict[str, int]:
    """Deletes the matching records, or the first n in primary key order: Milvus deletes take no limit."""
    keys = _keys(client, collection_name, primary_key, filter, [partition_name] if partition_name else None)
    if limit is not None:
        keys = keys[:limit]
    deleted = 0
    for start in range(0, len(keys), _PAGE):
        deleted += delete_rows(client, collection_name, ids=keys[start:start + _PAGE],
                               partition_name=partition_name)["delete_count"]
    return {"delete_count": deleted}


def sample_rows(client: Any, collection_name: str, primary_key: str, size: int, output_fields: Sequence[str],
                first: bool = False, filter: str = "", partition_names: Sequence[str] | None = None,
                consistency_level: str | None = None) -> list[dict[str, Any]]:
    """Exactly min(size, matches) records: a uniform draw over the matching keys, or the first ones in key order."""
    keys = _keys(client, collection_name, primary_key, filter, partition_names)
    chosen = keys[:size] if first else sorted(random.sample(keys, min(size, len(keys))))
    if not chosen:
        return []
    rows = {row[primary_key]: row for row in get_rows(client, collection_name, chosen, [primary_key, *output_fields],
                                                       partition_names=partition_names)}
    return [rows[key] for key in chosen]


def _rest(client: Any, path: str, body: dict[str, Any]) -> dict[str, Any]:
    """POST to the Milvus RESTful API v2 at the endpoint the client was opened with (for calls the SDKs lack)."""
    options = _endpoints.get(id(client))
    if options is None:
        raise RuntimeError("the client was not opened with rt.connect, so its REST endpoint is unknown")
    headers = {"Content-Type": "application/json"}
    token = options.get("token") or (f"{options['user']}:{options['password']}" if options.get("user") else None)
    if token:
        headers["Authorization"] = f"Bearer {token}"
    if options.get("db_name"):
        body = {"dbName": options["db_name"], **body}
    request = urllib.request.Request(str(options["uri"]).rstrip("/") + "/v2/vectordb" + path,
                                     data=json.dumps(body).encode("utf-8"), headers=headers, method="POST")
    with urllib.request.urlopen(request) as response:
        reply = json.loads(response.read().decode("utf-8"))
    if reply.get("code", 0) != 0:
        raise RuntimeError(f"Milvus REST {path} failed: {reply.get('message', reply)}")
    return reply.get("data") or {}


def bulk_import(client: Any, collection_name: str, files: Sequence[Sequence[str]], partition_name: str | None = None,
                wait: bool = True, timeout: float | None = None) -> dict[str, Any]:
    """Starts a Milvus import job over files in the server's bucket and, unless asked not to, waits for it."""
    body: dict[str, Any] = {"collectionName": collection_name, "files": [list(group) for group in files]}
    if partition_name:
        body["partitionName"] = partition_name
    job_id = str(_rest(client, "/jobs/import/create", body)["jobId"])
    if not wait:
        return {"job_id": job_id}
    deadline = None if timeout is None else time.monotonic() + timeout
    while True:
        progress = _rest(client, "/jobs/import/describe", {"jobId": job_id})
        state = progress.get("state")
        if state == "Completed":
            return {"job_id": job_id, "state": state, "imported_rows": int(progress.get("importedRows", 0))}
        if state == "Failed":
            raise RuntimeError(f"import job {job_id} into {collection_name} failed: {progress.get('reason', '')}")
        if deadline is not None and time.monotonic() > deadline:
            raise TimeoutError(f"import job {job_id} did not finish within {timeout} s")
        time.sleep(1)


def drop_aliases(client: Any, collection_name: str) -> None:
    for alias in client.list_aliases(collection_name)["aliases"]:
        client.drop_alias(alias)


def create_snapshot(client: Any, collection_name: str, snapshot_name: str, description: str = "") -> None:
    """Flushes first: a snapshot records sealed segments, so writes and deletes still in memory would be missing."""
    client.flush(collection_name)
    client.create_snapshot(snapshot_name, collection_name, description=description)


def _snapshot_owner(client: Any, snapshot_name: str) -> str:
    owners = [name for name in client.list_collections()
              if snapshot_name in client.list_snapshots(collection_name=name)]
    if len(owners) != 1:
        raise ValueError(f"snapshot {snapshot_name} belongs to {len(owners)} collections; name its collection")
    return owners[0]


def restore_snapshot(client: Any, snapshot_name: str, collection_name: str, source_collection_name: str | None = None,
                     wait: bool = True, timeout: float | None = None) -> dict[str, Any]:
    """Restores a snapshot into a new collection and, when waiting, loads it so it serves queries."""
    source = source_collection_name or _snapshot_owner(client, snapshot_name)
    job_id = client.restore_snapshot(snapshot_name, source, collection_name)
    if not wait:
        return {"job_id": job_id}
    deadline = None if timeout is None else time.monotonic() + timeout
    while True:
        info = client.get_restore_snapshot_state(job_id)
        state = str(info.state)
        if state == "RestoreSnapshotCompleted":
            client.load_collection(collection_name)
            return {"job_id": job_id, "state": state}
        if state == "RestoreSnapshotFailed":
            raise RuntimeError(f"restoring {snapshot_name} into {collection_name} failed: {info.reason}")
        if deadline is not None and time.monotonic() > deadline:
            raise TimeoutError(f"restoring {snapshot_name} did not finish within {timeout} s")
        time.sleep(1)


def drop_snapshot(client: Any, snapshot_name: str, collection_name: str | None = None) -> None:
    client.drop_snapshot(snapshot_name, collection_name or _snapshot_owner(client, snapshot_name))


def clone_collection(client: Any, collection_name: str, target_name: str) -> dict[str, Any]:
    """A materialized copy: a temporary snapshot restored under the new name, then dropped."""
    snapshot = f"vecdsl_clone_{target_name}"
    create_snapshot(client, collection_name, snapshot)
    try:
        restore_snapshot(client, snapshot, target_name, source_collection_name=collection_name)
    finally:
        drop_snapshot(client, snapshot, collection_name)
    return {"collection": target_name, "count": count(client, target_name, consistency_level="Strong")}

